package uk.ac.ravensbourne.casevault.service;
import io.github.bucket4j.Bandwidth; import io.github.bucket4j.Bucket; import io.github.bucket4j.Refill; import java.time.Duration; import java.util.UUID; import java.util.concurrent.ConcurrentHashMap; import org.springframework.stereotype.Service; import uk.ac.ravensbourne.casevault.audit.PersistentAuditService; import uk.ac.ravensbourne.casevault.security.UserPrincipal;
/** Rate-limits denial audit attempts so probes cannot exhaust the audit trail (CWE-770). */
@Service public class AccessDeniedAuditService { private final ConcurrentHashMap<java.util.UUID,Bucket> buckets=new ConcurrentHashMap<>(); private final PersistentAuditService audit; public AccessDeniedAuditService(PersistentAuditService audit){this.audit=audit;} public void record(UserPrincipal p,String target){var bucket=buckets.computeIfAbsent(p.id(),id->Bucket.builder().addLimit(Bandwidth.classic(20, Refill.greedy(20,Duration.ofMinutes(1)))).build());if(bucket.tryConsume(1))audit.recordDenied(p,"CASE",UUID.fromString(target.substring(target.indexOf(':')+1)));} }
